package com.bank.payments.application;

import com.bank.payments.adapters.in.rest.DebitAccountRequest;
import com.bank.payments.adapters.in.rest.DebitAccountResponse;
import com.bank.payments.domain.error.BusinessError;
import com.bank.payments.domain.model.Account;
import com.bank.payments.domain.port.AccountRepository;
import java.math.BigDecimal;
import java.util.Optional;

/**
 * Application service of DebitAccount (legacy PAGODEB).
 *
 * UNRESOLVED_DEPENDENCY: the value of CTA-ESTADO that makes CTA-ACTIVA true is defined in
 * copybook CTAREG, which is not provided. The value "A" is used as the active value, as encoded
 * by the tests; any other value is treated as not active.
 */
public class DebitAccountService {

    private static final String ACTIVE_STATUS = "A";

    private final AccountRepository accountRepository;

    public DebitAccountService(AccountRepository accountRepository) {
        this.accountRepository = accountRepository;
    }

    public DebitAccountResponse execute(DebitAccountRequest request) {
        // READ FILE('CUENTAS') ... UPDATE
        Optional<Account> found = accountRepository.findByNumberForUpdate(request.accountNumber());

        // WHEN WS-RESP = DFHRESP(NOTFND) -> '30'
        if (found.isEmpty()) {
            throw new BusinessError("ACCOUNT_NOT_FOUND", "30", "CUENTA NO VALIDA");
        }
        Account account = found.get();

        // WHEN CTA-TIPO NOT = DEB-TIPO -> '40' (fixed-length text comparison: trailing blanks are not significant)
        if (!sameFixedText(account.accountType(), request.accountType())) {
            throw new BusinessError("ACCOUNT_TYPE_MISMATCH", "40", "CUENTA NO VALIDA");
        }

        // WHEN NOT CTA-ACTIVA -> '10'
        if (!ACTIVE_STATUS.equals(account.status())) {
            throw new BusinessError("ACCOUNT_INACTIVE", "10", "CUENTA INACTIVA");
        }

        // WHEN CTA-SALDO < DEB-MONTO -> '20'
        if (account.balance().compareTo(request.amount()) < 0) {
            throw new BusinessError("INSUFFICIENT_FUNDS", "20", "SALDO INSUFICIENTE");
        }

        // WHEN OTHER -> 1000-DEBITAR: SUBTRACT, REWRITE, DEB-RESP = '00'
        BigDecimal newBalance = account.balance().subtract(request.amount());
        accountRepository.updateBalance(account.accountNumber(), newBalance);
        return new DebitAccountResponse(newBalance, "00");
    }

    private static boolean sameFixedText(String a, String b) {
        if (a == null || b == null) {
            return a == b;
        }
        return stripTrailingBlanks(a).equals(stripTrailingBlanks(b));
    }

    private static String stripTrailingBlanks(String s) {
        int end = s.length();
        while (end > 0 && s.charAt(end - 1) == ' ') {
            end--;
        }
        return s.substring(0, end);
    }
}
